#!/usr/bin/env node
/**
 * Bundles src/viewer/webview/main.js and everything it imports into ONE self-contained
 * HTML string, written to src/viewer/webview/sheetWebViewHtml.js. The phone WebView loads
 * that string, so the tile viewer reaches phones with an ordinary OTA update (no native
 * module, no network fetch of the page).
 *
 *   node scripts/build-sheet-webview.cjs          rewrite the generated file
 *   node scripts/build-sheet-webview.cjs --check  exit 1 if it is out of date
 *
 * No bundler dependency: the engine modules are plain ES modules, transformed to
 * CommonJS with Babel and wrapped in a tiny module registry. A test fails when the
 * generated file does not match its sources, so the page cannot silently drift.
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const babel = require('@babel/core');

const VIEWER = path.join(__dirname, '..', 'src', 'viewer');
const ENTRY = 'webview/main.js';
const OUT = path.join(VIEWER, 'webview', 'sheetWebViewHtml.js');

function resolveImport(fromId, spec) {
  const base = path.posix.normalize(path.posix.join(path.posix.dirname(fromId), spec));
  for (const cand of [base, `${base}.js`]) {
    if (fs.existsSync(path.join(VIEWER, cand)) && fs.statSync(path.join(VIEWER, cand)).isFile()) return cand;
  }
  throw new Error(`cannot resolve ${spec} from ${fromId}`);
}

function collect() {
  const modules = {};
  const order = [];
  (function visit(id) {
    if (modules[id]) return;
    const src = fs.readFileSync(path.join(VIEWER, id), 'utf8');
    const deps = {};
    const { code } = babel.transformSync(src, {
      filename: path.join(VIEWER, id), configFile: false, babelrc: false, comments: false, compact: false,
      plugins: [require.resolve('@babel/plugin-transform-modules-commonjs'),
        function collectDeps() {
          return { visitor: { CallExpression(p) {
            const n = p.node;
            if (n.callee.name === 'require' && n.arguments[0] && n.arguments[0].type === 'StringLiteral') {
              const spec = n.arguments[0].value;
              if (!spec.startsWith('.')) throw new Error(`${id} imports a package (${spec}); the page has none`);
              deps[spec] = resolveImport(id, spec);
            }
          } } };
        }],
    });
    modules[id] = { code, deps, src };
    order.push(id);
    Object.values(deps).forEach(visit);
  }(ENTRY));
  return { modules, order };
}

function build() {
  const { modules, order } = collect();
  const hash = crypto.createHash('sha256');
  for (const id of order.slice().sort()) hash.update(id).update(modules[id].src);
  const sourceHash = hash.digest('hex').slice(0, 16);
  const defs = order.map((id) => {
    const m = modules[id];
    return `${JSON.stringify(id)}:[function(exports,module,require){${m.code}\n},${JSON.stringify(m.deps)}]`;
  }).join(',\n');
  const bundle = `(function(){var D={${defs}};var C={};function R(id){if(C[id])return C[id].exports;var d=D[id];var m=C[id]={exports:{}};d[0](m.exports,m,function(s){return R(d[1][s]);});return m.exports;}R(${JSON.stringify(ENTRY)});})();`;
  const html = '<!doctype html><html><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">'
    + '<style>html,body,#root{margin:0;height:100%;overflow:hidden;background:#131E27;overscroll-behavior:none;-webkit-touch-callout:none;-webkit-user-select:none;user-select:none}</style>'
    + '</head><body><div id="root"></div><script>'
    + bundle.replace(/<\/script/gi, '<\\/script')
    + '</script></body></html>';
  const file = '// GENERATED by scripts/build-sheet-webview.cjs from src/viewer; do not edit.\n'
    + '// Run: node scripts/build-sheet-webview.cjs   (a test fails when this is out of date)\n'
    + `export const SHEET_WEBVIEW_SOURCE_HASH = ${JSON.stringify(sourceHash)};\n`
    + `export const SHEET_WEBVIEW_HTML = ${JSON.stringify(html)};\n`;
  return { file, sourceHash, bytes: html.length, modules: order };
}

module.exports = { build, OUT };

if (require.main === module) {
  const { file, sourceHash, bytes, modules } = build();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
    if (current !== file) {
      console.error('src/viewer/webview/sheetWebViewHtml.js is out of date. Run: node scripts/build-sheet-webview.cjs');
      process.exit(1);
    }
    console.log(`up to date (${sourceHash}, ${modules.length} modules, ${(bytes / 1024).toFixed(0)} KB)`);
  } else {
    fs.writeFileSync(OUT, file);
    console.log(`wrote ${path.relative(process.cwd(), OUT)} (${sourceHash}, ${modules.length} modules, ${(bytes / 1024).toFixed(0)} KB)`);
  }
}
